class Solution:
    def maximumCoins(self, heroes: List[int], monsters: List[int], coins: List[int]) -> List[int]:
        pairs = sorted(zip(monsters, coins))
        m = len(pairs)
        powers = [p[0] for p in pairs]
        pref = [0] * (m + 1)
        for i in range(m):
            pref[i + 1] = pref[i] + pairs[i][1]
        ans = []
        for h in heroes:
            idx = bisect_right(powers, h)
            ans.append(pref[idx])
        return ans

class Solution {
public:
    vector<long long> maximumCoins(vector<int>& heroes, vector<int>& monsters, vector<int>& coins) {
        int m = monsters.size();
        vector<pair<int, int>> pairs(m);
        for (int i = 0; i < m; i++) pairs[i] = {monsters[i], coins[i]};
        sort(pairs.begin(), pairs.end());
        vector<int> powers(m);
        vector<long long> pref(m + 1, 0);
        for (int i = 0; i < m; i++) {
            powers[i] = pairs[i].first;
            pref[i + 1] = pref[i] + pairs[i].second;
        }
        vector<long long> ans;
        ans.reserve(heroes.size());
        for (int h : heroes) {
            int idx = upper_bound(powers.begin(), powers.end(), h) - powers.begin();
            ans.push_back(pref[idx]);
        }
        return ans;
    }
};

class Solution {
    public long[] maximumCoins(int[] heroes, int[] monsters, int[] coins) {
        int m = monsters.length;
        int[][] pairs = new int[m][2];
        for (int i = 0; i < m; i++) {
            pairs[i][0] = monsters[i];
            pairs[i][1] = coins[i];
        }
        Arrays.sort(pairs, (a, b) -> Integer.compare(a[0], b[0]));
        int[] powers = new int[m];
        long[] pref = new long[m + 1];
        for (int i = 0; i < m; i++) {
            powers[i] = pairs[i][0];
            pref[i + 1] = pref[i] + pairs[i][1];
        }
        long[] ans = new long[heroes.length];
        for (int i = 0; i < heroes.length; i++) {
            int idx = upperBound(powers, heroes[i]);
            ans[i] = pref[idx];
        }
        return ans;
    }
    private int upperBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (arr[mid] <= target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

/**
 * @param {number[]} heroes
 * @param {number[]} monsters
 * @param {number[]} coins
 * @return {number[]}
 */
var maximumCoins = function(heroes, monsters, coins) {
    const m = monsters.length;
    const pairs = [];
    for (let i = 0; i < m; i++) pairs.push([monsters[i], coins[i]]);
    pairs.sort((a, b) => a[0] - b[0]);
    const powers = pairs.map(p => p[0]);
    const pref = new Array(m + 1).fill(0);
    for (let i = 0; i < m; i++) pref[i + 1] = pref[i] + pairs[i][1];
    const ans = [];
    for (const h of heroes) {
        let lo = 0, hi = m;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (powers[mid] <= h) lo = mid + 1;
            else hi = mid;
        }
        ans.push(pref[lo]);
    }
    return ans;
};
